matrix.CS=matrix.CS[:matrix.CS.index("class ProbeAcceptance")]+'\nclass ProbeAcceptance {\n static Dictionary<string,object> D(object x){return Cad.Json.Deserialize<Dictionary<string,object>>(Cad.Json.Serialize(x));}\n [STAThread]static int Main(string[] a){if(a.Length==2&&a[0]=="--isolated-probe")return Cad.IsolatedProbeWorker(a[1]);var r=new Dictionary<string,object>{{"completed",false}};Cad cad=null;int pid=int.Parse(a[2]);Action save=()=>File.WriteAllText(Path.Combine(a[0],"native.json"),Cad.Json.Serialize(r));using(var gate=new Mutex(false,@"Local\\SolidWorksClashMate_MechDog_Executor")){if(!gate.WaitOne(0))return 4;try{cad=new Cad(a[0]);if(cad.Sw.GetProcessID()!=pid||(cad.Sw.GetDocuments() as object[]??new object[0]).Length!=0)throw new Exception("OWNED_INSTANCE_NOT_EMPTY");var imported=D(cad.ImportUserAssembly(a[1],""));string id=(string)imported["model_id"];r["import"]=imported;save();var candidates=D(cad.UserDriveCandidates(id,"","cylindrical_axis",50,null));var rows=Cad.Json.Deserialize<Dictionary<string,object>[]>(Cad.Json.Serialize(candidates["entities"]));var selected=rows.First();r["created"]=cad.CreateUserStudy(id,"SnapshotReplayAcceptance",(string)selected["component_id"],(string)selected["entity_id"],"rotary",30,false,"",1,30);save();string run=Guid.NewGuid().ToString("N");r["run"]=cad.RunUserStudy(id,"SnapshotReplayAcceptance",1,30,run);save();cad.AcceptanceEditProperty(id);try{cad.ReplayUserFrame(run,15);throw new Exception("STRICT_REPLAY_NOT_BLOCKED");}catch(CadFault e){if(e.Code!="MODEL_REVISION_CHANGED")throw;r["strict_replay_code"]=e.Code;}save();r["snapshot_replay"]=cad.ReplayFrozenSnapshot(run,15);save();r["negative"]=cad.AcceptanceBadSnapshot(run);r["branch"]=cad.AcceptanceResetBranch(id);r["completed"]=true;save();return 0;\n }catch(Exception e){r["error"]=e.ToString();r["details"]=e is CadFault?((CadFault)e).Diagnostics:null;save();return 1;}finally{if(cad!=null)try{cad.ProbeTestExit(pid);}catch(Exception e){r["cleanup_error"]=e.ToString();}save();gate.ReleaseMutex();}}}\n}\npublic partial class Cad {\n public void AcceptanceEditProperty(string id){var model=GetUserModel(id);using(var scope=new Scope(this,model.Path,null)){scope.Doc.Extension.CustomPropertyManager[""].Add3("SnapshotReplayAcceptance",30,"changed-current-input",1);Save(scope.Doc,model.Path);model.Revision++;SaveUserModel(model);}}\n public object AcceptanceBadSnapshot(string run){string file=Path.Combine(Root,"runs",run,"solve.json");byte[] before=File.ReadAllBytes(file);try{var data=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));((Dictionary<string,object>)data["replay_input_snapshot"])["sha256"]="bad";AtomicJson(file,data);try{ReplayFrozenSnapshot(run,15);throw new Exception("BAD_SNAPSHOT_ACCEPTED");}catch(Exception e){if(e.Message!="REPLAY_SNAPSHOT_INTEGRITY_FAILED")throw;return new{blocked=true,code=e.Message};}}finally{File.WriteAllBytes(file,before);}}\n public object AcceptanceResetBranch(string id){var model=GetUserModel(id);using(var scope=new Scope(this,model.Path,null)){var manager=(IMotionStudyManager)scope.Doc.Extension.GetMotionStudyManager();var study=(IMotionStudy)manager.GetMotionStudy("SnapshotReplayAcceptance");study.Activate();study.SetDuration(1);var props=(IMotionStudyProperties)study.GetProperties(4);props.SetFrameRate(30);study.Calculate();study.Stop();study.SetTime(.5);if(Math.Abs(study.GetTime()-.5)>1e-8)throw new Exception("TEST_NONZERO_CLOCK_NOT_ESTABLISHED");props.SetFrameRate(2500);SaveOwnedDocuments(model);Save(scope.Doc,model.Path);}var cp=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(CreateUserCheckpoint(id)));return ResetStudyInNewModel(id,"SnapshotReplayAcceptance",30,true,(string)cp["checkpoint_id"]);}\n}\n'
